function instrument(batch, group) {
  const name = group.dataItem;
  return {
    name,
    version: `EP Batch ${batch} · ${name} v1.0`,
    description: `headspace EP 2025 Batch ${batch} coded field capture. Follow the approved assessment protocol for clinical use.`,
    respondents: ["Person"],
    sections: [{ id: "fields", title: name }],
    questions: group.variables,
    codebookBatch: batch,
    codebookDataItem: name,
    mvpOnly: true,
  };
}

export const EP_BATCH_2_INSTRUMENTS = BATCH_2_GROUPS.map(group => instrument(2, group));
export const EP_BATCH_3_INSTRUMENTS = BATCH_3_GROUPS.map(group => instrument(3, group));
